pub fn unsafe_get_desired_temp() -> Option<Isolette_Data_Model::Set_Points>
{
  unsafe {
    let value: *mut Isolette_Data_Model::Set_Points = &mut Isolette_Data_Model::Set_Points::default();
    if (get_desired_temp(value)) {
      return Some(*value);
    } else {
      return None;
    }
  }
}

