#[cfg(test)]
lazy_static::lazy_static! {
  // simulate the global C variables that point to the microkit shared memory regions.  In a full
  // microkit system we would be able to mutate the shared memory for out ports since they're r/w,
  // but we couldn't do that for in ports since they are read-only
  pub static ref IN_current_temp: Mutex<Option<Isolette_Data_Model::Temp>> = Mutex::new(None);
  pub static ref IN_temp_changed: Mutex<Option<u8>> = Mutex::new(None);
  pub static ref IN_desired_temp: Mutex<Option<Isolette_Data_Model::Set_Points>> = Mutex::new(None);
  pub static ref OUT_heat_control: Mutex<Option<Isolette_Data_Model::On_Off>> = Mutex::new(None);
  pub static ref OUT_sv_currentSetPoints: Mutex<Option<Isolette_Data_Model::Set_Points>> = Mutex::new(None);
  pub static ref OUT_sv_lastCmd: Mutex<Option<Isolette_Data_Model::On_Off>> = Mutex::new(None);
  pub static ref INJECTION_ENABLED: Mutex<Option<bool>> = Mutex::new(None);
  pub static ref INJ_SV_currentSetPoints: Mutex<Option<Isolette_Data_Model::Set_Points>> = Mutex::new(None);
  pub static ref INJ_SV_lastCmd: Mutex<Option<Isolette_Data_Model::On_Off>> = Mutex::new(None);
  pub static ref MONITORING_ENABLED: Mutex<Option<bool>> = Mutex::new(None);
}

#[cfg(test)]
pub fn initialize_test_globals() {
  unsafe {
    *IN_current_temp.lock().unwrap_or_else(|e| e.into_inner()) = None;
    *IN_temp_changed.lock().unwrap_or_else(|e| e.into_inner()) = None;
    *IN_desired_temp.lock().unwrap_or_else(|e| e.into_inner()) = None;
    *OUT_heat_control.lock().unwrap_or_else(|e| e.into_inner()) = None;
    *OUT_sv_currentSetPoints.lock().unwrap_or_else(|e| e.into_inner()) = None;
    *OUT_sv_lastCmd.lock().unwrap_or_else(|e| e.into_inner()) = None;
    *INJECTION_ENABLED.lock().unwrap_or_else(|e| e.into_inner()) = None;
    *INJ_SV_currentSetPoints.lock().unwrap_or_else(|e| e.into_inner()) = None;
    *INJ_SV_lastCmd.lock().unwrap_or_else(|e| e.into_inner()) = None;
    *MONITORING_ENABLED.lock().unwrap_or_else(|e| e.into_inner()) = None;
  }
}

